function translate(){const dict={...fallback,...langs.en,...langs[activeLang]};document.documentElement.lang=activeLang;document.querySelectorAll('[data-i18n]').forEach(el=>{const text=dict[el.dataset.i18n];if(text)el.textContent=text});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const text=dict[el.dataset.i18nPlaceholder];if(text)el.placeholder=text});document.querySelector('#language').value=activeLang;document.title=document.title.replace(/^.*? \| /,'')+' | JasaTiketMurah';}
translate();document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#language').addEventListener('change',e=>{activeLang=e.target.value;localStorage.setItem('jtm-language',activeLang);translate()});document.querySelector('.menu-toggle').addEventListener('click',()=>document.querySelector('.main-nav').classList.toggle('open'));
