if(bookingForm){
  const tabs=document.createElement('div');tabs.className='trip-types';tabs.innerHTML='<label><input type="radio" name="trip-type" value="one-way" checked> Sekali jalan</label><label><input type="radio" name="trip-type" value="round-trip"> Pulang-pergi</label><label><input type="radio" name="trip-type" value="multi-city"> Multi-kota</label>';
  document.querySelector('.search-card').insertBefore(tabs,bookingForm);tabs.insertAdjacentHTML('beforeend','<label class="direct-choice"><input type="checkbox" name="direct-only"> <span data-runtime="direct">Penerbangan langsung</span></label>');
  const travellerLabel=bookingForm.querySelectorAll('label')[3];
  travellerLabel.innerHTML='<small>Penumpang</small><button type="button" class="traveller-trigger" aria-expanded="false">1 dewasa</button><div class="traveller-popover" hidden><div class="traveller-row"><span><b>Dewasa</b><small>12 tahun ke atas</small></span><div class="counter"><button type="button" data-counter="adults" data-step="-1">−</button><output data-count="adults">1</output><button type="button" data-counter="adults" data-step="1">+</button></div></div><div class="traveller-row"><span><b>Anak</b><small>2–11 tahun</small></span><div class="counter"><button type="button" data-counter="children" data-step="-1">−</button><output data-count="children">0</output><button type="button" data-counter="children" data-step="1">+</button></div></div><div class="traveller-row"><span><b>Bayi</b><small>Di bawah 2 tahun</small></span><div class="counter"><button type="button" data-counter="infants" data-step="-1">−</button><output data-count="infants">0</output><button type="button" data-counter="infants" data-step="1">+</button></div></div><p class="traveller-note">Maksimal 7 penumpang per pemesanan.</p><button type="button" class="traveller-done">Selesai</button></div>';
  const state={adults:1,children:0,infants:0};const trigger=travellerLabel.querySelector('.traveller-trigger');const popover=travellerLabel.querySelector('.traveller-popover');
  const refreshTravellers=()=>{Object.entries(state).forEach(([key,value])=>travellerLabel.querySelector(`[data-count="${key}"]`).textContent=value);const pieces=[];if(state.adults)pieces.push(`${state.adults} dewasa`);if(state.children)pieces.push(`${state.children} anak`);if(state.infants)pieces.push(`${state.infants} bayi`);trigger.textContent=pieces.join(', ');travellerLabel.querySelectorAll('.counter button[data-step="1"]').forEach(button=>button.disabled=state.adults+state.children+state.infants>=7);travellerLabel.querySelector('[data-counter="adults"][data-step="-1"]').disabled=state.adults<=1;['children','infants'].forEach(key=>travellerLabel.querySelector(`[data-counter="${key}"][data-step="-1"]`).disabled=state[key]===0)};
  trigger.addEventListener('click',()=>{popover.hidden=!popover.hidden;trigger.setAttribute('aria-expanded',String(!popover.hidden))});travellerLabel.querySelector('.traveller-done').addEventListener('click',()=>{popover.hidden=true;trigger.setAttribute('aria-expanded','false')});travellerLabel.querySelectorAll('[data-counter]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.counter;const next=state[key]+Number(button.dataset.step);if(next>=0&&state.adults+state.children+state.infants+Number(button.dataset.step)<=7&&(key!=='adults'||next>=1)){state[key]=next;refreshTravellers()}}));refreshTravellers();
  const departure=document.querySelector('#travel-date');const returnField=document.createElement('label');returnField.className='return-date';returnField.innerHTML='<small>Tanggal pulang</small><input id="return-date" type="date" disabled aria-disabled="true">';departure.parentElement.after(returnField);const returnDate=returnField.querySelector('input');
  const syncReturn=()=>{returnDate.min=departure.value||new Date().toISOString().slice(0,10);if(returnDate.value&&returnDate.value<returnDate.min)returnDate.value=returnDate.min};departure.addEventListener('change',syncReturn);syncReturn();
  tabs.addEventListener('change',event=>{if(event.target.name!=='trip-type')return;if(event.target.value==='multi-city'){window.location.href='/multi-city/';return}const returning=event.target.value==='round-trip';returnDate.disabled=!returning;returnDate.setAttribute('aria-disabled',String(!returning));returnDate.required=returning;if(returning&&!returnDate.value)returnDate.value=returnDate.min});
  bookingForm.addEventListener('submit',event=>{if(returnDate.disabled===false&&returnDate.value<departure.value){event.preventDefault();document.querySelector('#search-feedback').textContent='Tanggal pulang tidak boleh lebih awal dari tanggal berangkat.'}});
}

document.head.insertAdjacentHTML('beforeend','<style>.trip-types{display:flex;gap:18px;padding:16px 0 4px;font-size:.88rem;font-weight:600;color:#334155}.trip-types label{display:flex;align-items:center;gap:6px;cursor:pointer}.trip-types input{accent-color:#1e3a8a}.traveller-trigger{height:48px;text-align:left;border:1px solid #cbd5e1;border-radius:5px;background:#fff;padding:10px;color:#0d1b2a;font:500 .91rem DM Sans;cursor:pointer}.traveller-popover{position:absolute;z-index:8;top:76px;right:0;width:320px;padding:14px;background:#fff;border:1px solid #cbd5e1;border-radius:8px;box-shadow:0 16px 35px rgba(13,27,42,.18)}.search-form label{position:relative}.traveller-row{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid #e2e8f0}.traveller-row span{display:grid}.traveller-row small{font-weight:400;color:#64748b}.counter{display:flex;align-items:center;gap:11px}.counter button{width:28px;height:28px;border:1px solid #cbd5e1;background:#fff;border-radius:50%;font-size:18px;color:#1e3a8a;cursor:pointer}.counter button:disabled{opacity:.35;cursor:not-allowed}.counter output{min-width:14px;text-align:center}.traveller-note{font-size:.76rem;color:#64748b;margin:11px 0}.traveller-done{width:100%;border:0;background:#1e3a8a;color:#fff;border-radius:4px;padding:9px;font-weight:700;cursor:pointer}@media(max-width:560px){.trip-types{gap:12px;overflow:auto;white-space:nowrap}.traveller-popover{position:fixed;inset:auto 16px 16px;width:auto}.return-date{display:block!important}}</style>');

