const languageSelect=document.querySelector('#language');if(languageSelect){languageSelect.innerHTML='<option value="id">🇮🇩 Indonesia</option><option value="en">🇬🇧 English</option><option value="km">🇰🇭 Khmer</option><option value="zh-Hans">🇨🇳 Chinese, Simplified</option><option value="zh-Hant">🇹🇼 Chinese, Traditional</option><option value="ja">🇯🇵 Japanese</option><option value="ko">🇰🇷 Korean</option><option value="ms">🇲🇾 Malay</option><option value="my">🇲🇲 Myanmar</option><option value="pt">🇵🇹 Portuguese</option><option value="fil">🇵🇭 Tagalog</option><option value="th">🇹🇭 Thai</option><option value="tr">🇹🇷 Turkish</option><option value="vi">🇻🇳 Vietnamese</option>';languageSelect.value=activeLang;languageSelect.insertAdjacentHTML('afterend','<select id="currency" class="currency-select" aria-label="Mata uang"><option value="IDR">IDR — Indonesia Rupiah</option><option value="AUD">AUD — Australian Dollar</option><option value="CAD">CAD — Canadian Dollar</option><option value="CNY">CNY — Chinese Yuan</option><option value="GBP">GBP — British Pound</option><option value="JPY">JPY — Japanese Yen</option><option value="KRW">KRW — South Korean Won</option><option value="MYR">MYR — Malaysian Ringgit</option><option value="NZD">NZD — New Zealand Dollar</option><option value="PHP">PHP — Philippine Peso</option><option value="SGD">SGD — Singapore Dollar</option><option value="USD">USD — United States Dollar</option><option value="VND">VND — Vietnamese Dong</option></select>');const currency=document.querySelector('#currency');currency.value=localStorage.getItem('jtm-currency')||'IDR';currency.addEventListener('change',()=>localStorage.setItem('jtm-currency',currency.value))}
document.querySelector('[data-service="tour"]')?.firstChild.replaceWith('🧭 ');document.querySelector('[data-service="visa"]')?.firstChild.replaceWith('🛂 ');document.querySelectorAll('.service-tile').forEach(tile=>{if(tile.querySelector('[data-i18n="tour"]'))tile.firstChild.replaceWith('🧭');if(tile.querySelector('[data-i18n="visa"]'))tile.firstChild.replaceWith('🛂')});

