const groupForm=document.querySelector('#group-booking-form');if(groupForm){let groupAnswer;const groupCaptcha=()=>{const first=Math.floor(Math.random()*90)+10,second=Math.floor(Math.random()*(first+1));groupAnswer=first-second;document.querySelector('#group-captcha-label').textContent=`Verifikasi: ${first} − ${second} = `};groupCaptcha();groupForm.addEventListener('submit',async event=>{event.preventDefault();const feedback=document.querySelector('#group-booking-feedback');if(Number(document.querySelector('#group-captcha').value)!==groupAnswer){feedback.textContent=copy('verificationIncorrect');groupCaptcha();return}const payload=Object.fromEntries(new FormData(groupForm));feedback.textContent='Mengirim permintaan Anda…';try{const response=await fetch('/api/group-booking.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error();feedback.textContent='Permintaan terkirim. Salinan email telah dikirim ke alamat Anda.';groupForm.reset()}catch{sessionStorage.setItem('jtm-group-booking',JSON.stringify(payload));feedback.textContent='Permintaan tersimpan. Layanan email sedang tidak tersedia; tim kami akan menindaklanjuti.'}groupCaptcha()})}

// Checkout is intentionally client-side until payment and account services are connected.
const generateOrderNumber=(type='F')=>`JTM${type}${Math.floor(Date.now()/1000)}`;
document.querySelector('#flight-results')?.addEventListener('click',event=>{const button=event.target.closest('.result-price button');if(!button)return;const card=button.closest('.flight-result');const price=card.querySelector('.result-price b')?.textContent||'';const airline=card.querySelector('b')?.textContent||'';window.location.href=`/checkout/?airline=${encodeURIComponent(airline)}&price=${encodeURIComponent(price)}&route=${encodeURIComponent(document.querySelector('#result-route')?.textContent||'')}`});
const checkoutForm=document.querySelector('#checkout-form');if(checkoutForm){const query=new URLSearchParams(location.search);document.querySelector('#checkout-route').textContent=query.get('route')||'CGK → DPS';document.querySelector('#checkout-airline').textContent=query.get('airline')||'Batik Air';document.querySelector('#checkout-total').textContent=query.get('price')||'Rp1.189.000';document.querySelector('#checkout-date').textContent=new Intl.DateTimeFormat('id-ID',{dateStyle:'medium'}).format(new Date());checkoutForm.querySelectorAll('[name="bookingMode"]').forEach(input=>input.addEventListener('change',()=>{const member=input.value==='member'&&input.checked;const password=checkoutForm.querySelector('.member-password');password.hidden=!member;password.querySelector('input').required=member}));checkoutForm.addEventListener('submit',event=>{event.preventDefault();const orderNumber=generateOrderNumber('F');sessionStorage.setItem('jtm-order',JSON.stringify({number:orderNumber,customer:Object.fromEntries(new FormData(checkoutForm)),route:query.get('route'),price:query.get('price')}));window.location.href=`/order-confirmation/?order=${orderNumber}`})}
const confirmation=document.querySelector('#order-number');if(confirmation){const order=new URLSearchParams(location.search).get('order')||JSON.parse(sessionStorage.getItem('jtm-order')||'{}').number||generateOrderNumber('F');confirmation.textContent=order;const detail=JSON.parse(sessionStorage.getItem('jtm-order')||'{}');if(detail.customer?.email)document.querySelector('#order-confirmation-detail').textContent=`Ringkasan pesanan dikirim ke ${detail.customer.email}.`}

const runtimeCopy=()=>window.JTM_I18N?.runtime?.[activeLang]||window.JTM_I18N?.runtime?.en||{departure:'Departure date',return:'Return date',passengers:'Passengers',bookingClass:'Booking class',oneWay:'One way',roundTrip:'Round trip',multiCity:'Multi-city',direct:'Direct flights only',adult:'adult',child:'child',infant:'infant'};
const refreshDynamicLocale=()=>{const copy=runtimeCopy();document.querySelector('#travel-date')?.previousElementSibling&&(document.querySelector('#travel-date').previousElementSibling.textContent=copy.departure);document.querySelector('#return-date')?.parentElement.querySelector('small')&&(document.querySelector('#return-date').parentElement.querySelector('small').textContent=copy.return);document.querySelector('.traveller-trigger')?.previousElementSibling&&(document.querySelector('.traveller-trigger').previousElementSibling.textContent=copy.passengers);document.querySelectorAll('.trip-types label:not(.direct-choice)').forEach((label,index)=>label.lastChild.textContent=[' '+copy.oneWay,' '+copy.roundTrip,' '+copy.multiCity][index]);document.querySelector('[data-runtime="direct"]')&&(document.querySelector('[data-runtime="direct"]').textContent=copy.direct);document.querySelector('[data-runtime="bookingClass"]')&&(document.querySelector('[data-runtime="bookingClass"]').textContent=copy.bookingClass)};refreshDynamicLocale();document.querySelector('#language')?.addEventListener('change',()=>setTimeout(refreshDynamicLocale));document.addEventListener('jtm-i18n-ready',refreshDynamicLocale);
const refreshPassengerCopy=()=>{const copy=runtimeCopy();const values=['adults','children','infants'].map(key=>Number(document.querySelector(`[data-count="${key}"]`)?.textContent||0));const trigger=document.querySelector('.traveller-trigger');if(trigger)trigger.textContent=[values[0]&&`${values[0]} ${copy.adult}`,values[1]&&`${values[1]} ${copy.child}`,values[2]&&`${values[2]} ${copy.infant}`].filter(Boolean).join(', ');document.querySelectorAll('.traveller-row b').forEach((item,index)=>item.textContent=[copy.adult,copy.child,copy.infant][index])};refreshPassengerCopy();document.querySelector('#language')?.addEventListener('change',()=>setTimeout(refreshPassengerCopy));document.addEventListener('jtm-i18n-ready',refreshPassengerCopy);
setTimeout(()=>{const form=document.querySelector('#multi-city-form');if(!form)return;const airports=['Jakarta (CGK)','Denpasar (DPS)','Surabaya (SUB)','Yogyakarta (YIA)','Medan (KNO)','Singapore (SIN)','Kuala Lumpur (KUL)','Bangkok (BKK)','Tokyo (NRT)','Seoul (ICN)'];const list=document.createElement('datalist');list.id='multi-city-airports';list.innerHTML=airports.map(airport=>`<option value="${airport}">`).join('');document.body.appendChild(list);const decorate=()=>form.querySelectorAll('.route-row input:not([type="date"])').forEach(input=>{input.setAttribute('list','multi-city-airports');input.setAttribute('autocomplete','off')});decorate();new MutationObserver(decorate).observe(form,{childList:true,subtree:true})},0);

const charterForm=document.querySelector('#charter-form');if(charterForm){let charterAnswer;const charterCaptcha=()=>{const first=Math.floor(Math.random()*90)+10,second=Math.floor(Math.random()*(first+1));charterAnswer=first-second;document.querySelector('#charter-captcha-label').textContent=`${copy('verification')}: ${first} − ${second} = `};const tripType=charterForm.querySelector('[name="tripType"]'),returnField=charterForm.querySelector('.charter-return');const departureField=charterForm.querySelector('[name="departureDate"]'),returnDate=charterForm.querySelector('[name="returnDate"]');const todayDate=new Date().toISOString().slice(0,10);departureField.min=todayDate;returnDate.min=todayDate;tripType.addEventListener('change',()=>{const returning=tripType.value==='return';returnField.hidden=!returning;returnDate.required=returning;if(returning)returnDate.min=departureField.value||todayDate});departureField.addEventListener('change',()=>returnDate.min=departureField.value||todayDate);charterCaptcha();charterForm.addEventListener('submit',async event=>{event.preventDefault();const feedback=document.querySelector('#charter-feedback');if(Number(document.querySelector('#charter-captcha').value)!==charterAnswer){feedback.textContent=copy('verificationIncorrect');charterCaptcha();return}if(tripType.value==='return'&&returnDate.value<departureField.value){feedback.textContent='Tanggal pulang tidak boleh lebih awal dari tanggal pergi.';return}const payload=Object.fromEntries(new FormData(charterForm));feedback.textContent=copy('requestSending');try{const response=await fetch('/api/charter-request.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error();feedback.textContent=copy('requestSent');charterForm.reset();returnField.hidden=true}catch{feedback.textContent=copy('requestUnavailable')}charterCaptcha()})}

