if(bookingForm){const oldGroupLink=document.querySelector('.group-booking-link');oldGroupLink?.parentElement.remove();const groupLink=document.createElement('a');groupLink.className='group-booking-inline';groupLink.href='/group-booking/';groupLink.dataset.i18n='groupBookingCta';groupLink.textContent=copy('groupBookingCta');bookingForm.querySelector('.primary-button')?.before(groupLink);}
