const groupPassengerField=document.querySelector('.group-passenger-field');
if(groupPassengerField){const groupState={adults:1,children:0,infants:0};const trigger=groupPassengerField.querySelector('.group-passenger-trigger');const popover=groupPassengerField.querySelector('.group-passenger-popover');const refresh=()=>{Object.entries(groupState).forEach(([key,value])=>{groupPassengerField.querySelector(`[data-group-count="${key}"]`).textContent=value;groupPassengerField.querySelector(`[name="${key}"]`).value=value});trigger.textContent=[groupState.adults&&`${groupState.adults} dewasa`,groupState.children&&`${groupState.children} anak`,groupState.infants&&`${groupState.infants} bayi`].filter(Boolean).join(', ');groupPassengerField.querySelector('[data-group-counter="adults"][data-step="-1"]').disabled=groupState.adults<=1;['children','infants'].forEach(key=>groupPassengerField.querySelector(`[data-group-counter="${key}"][data-step="-1"]`).disabled=groupState[key]===0)};trigger.addEventListener('click',()=>{popover.hidden=!popover.hidden;trigger.setAttribute('aria-expanded',String(!popover.hidden))});groupPassengerField.querySelector('.group-passenger-done').addEventListener('click',()=>{popover.hidden=true;trigger.setAttribute('aria-expanded','false')});groupPassengerField.querySelectorAll('[data-group-counter]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.groupCounter;const next=groupState[key]+Number(button.dataset.step);if(next>=0&&(key!=='adults'||next>=1)){groupState[key]=next;refresh()}}));refresh();}
